UPDATE SHIP_INSTRUCTION_LINE
SET SALE_LINE_ID = #{saleLineId}, ITEM_ID = #{itemId}, ITEM_NAME = #{itemName},
	SPECIFICATION = #{specification}, UNIT = #{unit},
	QUANTITY = #{quantity}, NOTE = #{note}
WHERE SHIP_INSTRUCTION_LINE_ID = #{shipInstructionLineId}
AND SHIP_INSTRUCTION_ID = #{shipInstructionId} AND DELETED_YN = 'N'
